// 中文用途：对整链原型新增的20帧保存实际Detection叠图和联系表，供人工核查；原图不修改。
#include <opencv2/opencv.hpp>
#include <fstream>
#include <map>
#include <set>
int main(){std::ifstream ids("docs/evidence/112-forensics/deep/recovered_ids.txt");std::set<int>wanted;int v;while(ids>>v)wanted.insert(v);std::ifstream f("docs/evidence/112-forensics/deep/pipeline-cascade-full.jsonl");std::map<int,std::vector<cv::Point2f>>corners;std::string line;while(std::getline(f,line)){cv::FileStorage fs(line,cv::FileStorage::READ|cv::FileStorage::MEMORY|cv::FileStorage::FORMAT_JSON);int fid=fs["frame"];if(!wanted.count(fid))continue;for(auto d:fs["detections"])for(auto q:d){auto it=q.begin();float x=*it;++it;float y=*it;corners[fid].emplace_back(x,y);}}
cv::VideoCapture cap("data/raw/marker_video.avi");cv::Mat img,contact(4*360,5*640,CV_8UC3,cv::Scalar(15,15,15));int fid=0,slot=0;while(cap.read(img)){if(corners.count(fid)){auto c=corners[fid];cv::Mat annotated=img.clone();std::vector<cv::Point> pts;for(auto q:c)pts.emplace_back(cvRound(q.x),cvRound(q.y));cv::polylines(annotated,pts,true,{0,255,0},2,cv::LINE_AA);for(int i=0;i<4;++i){cv::drawMarker(annotated,pts[i],{0,0,255},cv::MARKER_CROSS,12,1);cv::putText(annotated,"C"+std::to_string(i),pts[i]+cv::Point(4,-6),cv::FONT_HERSHEY_SIMPLEX,.5,{0,255,255},1);}cv::putText(annotated,"f"+std::to_string(fid)+" cascade prototype / raw detection",{20,30},cv::FONT_HERSHEY_SIMPLEX,.7,{0,255,0},2);cv::imwrite("docs/evidence/112-forensics/deep/images/recovered-f"+std::to_string(fid)+".png",annotated);cv::Rect r=cv::boundingRect(pts);r.x-=35;r.y-=35;r.width+=70;r.height+=70;r&=cv::Rect(0,0,img.cols,img.rows);cv::Mat tile;cv::resize(annotated(r),tile,{640,360},0,0,cv::INTER_AREA);cv::putText(tile,"f"+std::to_string(fid),{10,25},cv::FONT_HERSHEY_SIMPLEX,.7,{0,255,255},2);tile.copyTo(contact(cv::Rect((slot%5)*640,(slot/5)*360,640,360)));++slot;}++fid;}cv::imwrite("docs/evidence/112-forensics/deep/images/recovered-contact.png",contact);}
